async function curriculumRequest(action,extra={}){if(location.port!=='4180')throw Error('Open the local service on port 4180.');const r=await fetch('/api/curriculum/'+action,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+governedToken},body:JSON.stringify({tenant:'scholarion',course:'AIM310',...extra})});const data=await r.json();if(!r.ok)throw Error(data.error);return data;}
function curriculumReviewPage(){return heading('Curriculum validation','Scholarion Academy · All courses: standard 10-week format')+`<section class="card prose"><p>Validate a proposed course package and save its review in the tenant database. Structural checks do not replace academic review. Publishing remains blocked until quality reviews and LMS integrations are complete.</p>${location.port!=='4180'?'<a class="button" href="http://127.0.0.1:4180/#curriculum-review">Open curriculum service</a>':''}<form id="curriculum-validate"><label>Course package JSON<textarea name="package" rows="16" required spellcheck="false">{"code":"AIM310","title":"Machine Learning I","format":"standard","weeklyHours":{"min":8,"max":10},"termWeeks":10,"competencies":[],"outcomes":[],"topics":[],"modules":[],"assessments":[]}</textarea></label><button class="button">Validate and save proposal</button></form><button class="button secondary" id="curriculum-history">Review history</button><div id="curriculum-results" aria-live="polite"></div></section>`;}
const beforeCurriculumReview=render;render=function(){if(location.hash==='#curriculum-review'){document.getElementById('app').innerHTML=integratedShell('curriculum-review',curriculumReviewPage(),model.role);bind();}else beforeCurriculumReview();document.querySelector('.sidebar nav')?.insertAdjacentHTML('beforeend',`<a class="nav-item" href="#curriculum-review">${icon('book')}Curriculum validation</a>`);};
document.addEventListener('submit',async e=>{const f=e.target;if(!['curriculum-connect','curriculum-validate'].includes(f.id))return;e.preventDefault();try{if(f.id==='curriculum-connect'){governedToken=new FormData(f).get('token');f.reset();toast('Token held in page memory.');return;}const result=await curriculumRequest('validate',{package:JSON.parse(new FormData(f).get('package'))});document.getElementById('curriculum-results').innerHTML=`<h2>${result.errors.length} structural issues</h2><p>Saved proposal ${esc(result.id)} · Publishing blocked</p><ul>${result.errors.map(x=>`<li><b>${esc(x.path)}</b>: ${esc(x.message)}</li>`).join('')}</ul><h3>Required review gates</h3>${listHTML(result.remainingReviews)}`;}catch(err){document.getElementById('curriculum-results').textContent=err.message;}});
document.addEventListener('click',async e=>{if(e.target.id!=='curriculum-history')return;try{const rows=await curriculumRequest('history');document.getElementById('curriculum-results').innerHTML=rows.map(r=>`<p>${esc(r.id)} · ${esc(new Date(r.created*1000).toLocaleString())} · ${JSON.parse(r.validation).length} structural issues</p>`).join('')||'<p>No proposals yet.</p>';}catch(err){document.getElementById('curriculum-results').textContent=err.message;}});
render();
